// Generated by npm run sync-docs. Edit the README files listed in docs/examples/manifest.json.
export const exampleDocs: Record<string, string> = {
  "minCalendar": "# MinCalendar 迷你日历\n\n提供紧凑的月份导航和日期选择，适合小型日期面板。\n\n## 交互指南\n\n1. 点击左右箭头切换月份。\n2. 点击日期，左侧示例会显示 onChange 返回的日期。\n3. 右侧点击“回到今天”，调用 ref.setDate 更新日历。\n\n## 在项目中运行\n\n点击本页的“运行演示”，或在独立窗口中体验示例。也可在 `src` 下的页面中直接挂载现有演示：\n\n```tsx\nimport Example from \"./components/miniCalendar/Demo\";\n\nexport default function ExamplePage() {\n  return <Example />;\n}\n```\n\n## API 与实现要点\n\n| 名称 | 类型或形式 | 说明 |\n| --- | --- | --- |\n| `value` | Date | 初始化显示日期，默认当前日期 |\n| `onChange` | (date: Date) => void | 点击日期时触发 |\n| `ref` | CalendarRef | getDate() 读取日期，setDate(date) 设置日期 |\n\n## 使用边界\n\nvalue 当前作为内部状态初始值，不会在父组件更新 value 时自动同步，因此不是完整的受控组件。需要主动更新时使用 ref.setDate。切换月份默认选中该月 1 日，但不会触发 onChange。\n\n## 源码位置\n\n- 演示入口：`src/components/miniCalendar/Demo.tsx`\n- 相关实现：`src/components/miniCalendar`\n",
  "calendar": "# Calendar 日历\n\n基于 Dayjs 的月视图日历，支持自定义日期单元格和语言设置。\n\n## 交互指南\n\n1. 通过页头切换月份，或点击今天回到当前日期。\n2. 点击单元格选择日期。\n3. 在 CalendarDemo 中查看 dateInnerContent 的自定义内容示例。\n\n## 在项目中运行\n\n点击本页的“运行演示”，或在独立窗口中体验示例。也可在 `src` 下的页面中直接挂载现有演示：\n\n```tsx\nimport Example from \"./components/calendar/CalendarDemo\";\n\nexport default function ExamplePage() {\n  return <Example />;\n}\n```\n\n## API 与实现要点\n\n| 名称 | 类型或形式 | 说明 |\n| --- | --- | --- |\n| `value` | Dayjs | 初始日期，必填 |\n| `onChange` | (date: Dayjs) => void | 选择日期和回到今天时触发 |\n| `dateRender` | (date: Dayjs) => ReactNode | 完全替换日期单元格 |\n| `dateInnerContent` | (date: Dayjs) => ReactNode | 追加单元格内容 |\n| `locale` | string | 语言标识；已提供 zh-CN、en-US |\n\n## 使用边界\n\nvalue 仅用于初始化内部日期和月份；后续 prop 变化不会自动同步。使用 Dayjs 值，不要直接传入原生 Date。\n\n## 源码位置\n\n- 演示入口：`src/components/calendar/CalendarDemo.tsx`\n- 相关实现：`src/components/calendar`\n",
  "icon": "# Icon 图标\n\n比较 Ant Design SVG、自定义 SVG 和 IconFont 三种图标封装方式。\n\n## 交互指南\n\n1. 切换小、中、大尺寸，观察图标和间距变化。\n2. 将指针移到 IconFont 图标上查看图标名称。\n3. 对照 Icon.tsx、createIcon.tsx 和 createFromIconFont.tsx 阅读封装。\n\n## 在项目中运行\n\n点击本页的“运行演示”，或在独立窗口中体验示例。也可在 `src` 下的页面中直接挂载现有演示：\n\n```tsx\nimport Example from \"./components/Icon/IconDemo\";\n\nexport default function ExamplePage() {\n  return <Example />;\n}\n```\n\n## API 与实现要点\n\n| 名称 | 类型或形式 | 说明 |\n| --- | --- | --- |\n| `style` | CSSProperties | 通过 fontSize、color 设置 SVG 图标 |\n| `spin` | boolean | 自定义 SVG 旋转效果 |\n| `type` | string | IconFont symbol 名称 |\n| `size` | string | IconFont 显示尺寸，例如 20px |\n\n## 使用边界\n\nIconFont 演示从阿里 CDN 加载外部脚本，需要网络。图标是否存在取决于该脚本提供的 symbol；不能将任意名称视作有效图标。\n\n## 源码位置\n\n- 演示入口：`src/components/Icon/IconDemo.tsx`\n- 相关实现：`src/components/Icon`\n",
  "qrCode": "# QRCode 二维码\n\n通过 Ant Design QRCode 展示编码内容，并演示尺寸控制。\n\n## 交互指南\n\n1. 点击加号放大二维码。\n2. 点击减号缩小二维码。\n3. 在边界尺寸下，对应按钮会禁用。\n\n## 在项目中运行\n\n点击本页的“运行演示”，或在独立窗口中体验示例。也可在 `src` 下的页面中直接挂载现有演示：\n\n```tsx\nimport Example from \"./components/QRCode/QrCode\";\n\nexport default function ExamplePage() {\n  return <Example />;\n}\n```\n\n## API 与实现要点\n\n| 名称 | 类型或形式 | 说明 |\n| --- | --- | --- |\n| `size` | number | 示例初始 220，每次增减 20，范围 200–600 |\n| `value` | string | 二维码编码内容，在示例源文件中设置 |\n| `errorLevel` | string | 示例使用 H 纠错等级 |\n\n## 使用边界\n\n当前页面没有编码内容输入框。复用时替换 value，避免把真实网络凭据提交到代码仓库。此示例是 Ant Design 组件的使用展示。\n\n## 源码位置\n\n- 演示入口：`src/components/QRCode/QrCode.tsx`\n- 相关实现：`src/components/QRCode`\n",
  "watermark": "# Watermark 水印\n\n在内容区域上方平铺文字水印，演示水印图案与 DOM 监听。\n\n## 交互指南\n\n1. 进入演示观察平铺文字。\n2. 修改 content 调整水印文字。\n3. 修改 gap、offset 和 fontStyle 比较间距、偏移和颜色。\n\n## 在项目中运行\n\n点击本页的“运行演示”，或在独立窗口中体验示例。也可在 `src` 下的页面中直接挂载现有演示：\n\n```tsx\nimport Example from \"./components/watermark/WatermarkDemo\";\n\nexport default function ExamplePage() {\n  return <Example />;\n}\n```\n\n## API 与实现要点\n\n| 名称 | 类型或形式 | 说明 |\n| --- | --- | --- |\n| `content` | string[] | 水印文字行 |\n| `gap` | [number, number] | 横向与纵向间隔 |\n| `offset` | [number, number] | 水印偏移 |\n| `fontStyle` | object | 字体样式，如 color |\n\n## 使用边界\n\n容器必须有可见宽高。水印用于内容标识，不能保证阻止截图、编辑或删除内容。\n\n## 源码位置\n\n- 演示入口：`src/components/watermark/WatermarkDemo.tsx`\n- 相关实现：`src/components/watermark`\n",
  "space": "# Space 间距\n\n统一子元素间距，支持水平、垂直、换行和分割元素。\n\n## 交互指南\n\n1. 切换排列方向。\n2. 开关换行与分割线。\n3. 使用加减按钮在 10–50 范围内调整间距。\n\n## 在项目中运行\n\n点击本页的“运行演示”，或在独立窗口中体验示例。也可在 `src` 下的页面中直接挂载现有演示：\n\n```tsx\nimport Example from \"./components/space/SpaceDemo\";\n\nexport default function ExamplePage() {\n  return <Example />;\n}\n```\n\n## API 与实现要点\n\n| 名称 | 类型或形式 | 说明 |\n| --- | --- | --- |\n| `direction` | horizontal / vertical | 排列方向 |\n| `size` | number | 子元素间距 |\n| `wrap` | boolean | 是否允许换行 |\n| `split` | ReactNode | 插入子元素之间的分隔内容 |\n\n## 使用边界\n\n可以用本目录 ConfigProvider 的 space.size 提供共享间距。示例分割线尺寸是固定的，业务中应按内容调整。\n\n## 源码位置\n\n- 演示入口：`src/components/space/SpaceDemo.tsx`\n- 相关实现：`src/components/space`\n",
  "codeDemo": "# Code 代码块\n\n基于 Monaco 的源码阅读面板，演示一个简化状态管理库的实现。\n\n## 交互指南\n\n1. 通过锁图标切换只读与编辑。\n2. 选择编辑器主题、切换缩略图。\n3. 双击文件名可修改显示名称，点击复制代码复制传入源码。\n\n## 在项目中运行\n\n点击本页的“运行演示”，或在独立窗口中体验示例。也可在 `src` 下的页面中直接挂载现有演示：\n\n```tsx\nimport Example from \"./components/code/CodeDemo\";\n\nexport default function ExamplePage() {\n  return <Example />;\n}\n```\n\n## API 与实现要点\n\n| 名称 | 类型或形式 | 说明 |\n| --- | --- | --- |\n| `id` | string | 编辑器配置的持久化标识 |\n| `codeString` | string | 显示的源码 |\n| `fileName` | string | 显示文件名 |\n| `onClick` | () => void | 可选收起代码回调 |\n\n## 使用边界\n\n编辑不会写回本地文件，复制按钮复制当前预览中的代码；切换页面或重置演示后恢复源码。配置保存在浏览器中。Monaco 资源默认从 CDN 加载；加载期间仍提供可阅读、复制的纯文本源码，离线环境如需编辑则需自行配置 loader。\n\n## 源码位置\n\n- 演示入口：`src/components/code/CodeDemo.tsx`\n- 相关实现：`src/components/code`\n",
  "popover": "# Popover 气泡卡片\n\n使用 Floating UI 定位浮层，可选择悬浮或点击触发。\n\n## 交互指南\n\n1. 将鼠标移到 Hover me 按钮上。\n2. 移开以关闭浮层。\n3. 重复操作，演示在关闭后随机切换 placement。\n\n## 在项目中运行\n\n点击本页的“运行演示”，或在独立窗口中体验示例。也可在 `src` 下的页面中直接挂载现有演示：\n\n```tsx\nimport Example from \"./components/popover/PopoverDemo\";\n\nexport default function ExamplePage() {\n  return <Example />;\n}\n```\n\n## API 与实现要点\n\n| 名称 | 类型或形式 | 说明 |\n| --- | --- | --- |\n| `content` | ReactNode | 浮层内容，必填 |\n| `trigger` | hover / click | 触发方式，默认 hover |\n| `placement` | AlignedPlacement | 方位及 start/end 对齐，默认 top |\n| `showArrow` | boolean | 显示箭头，默认 false |\n| `onOpenChange` | (open: boolean) => void | 打开状态改变通知 |\n\n## 使用边界\n\nopen 当前仅初始化内部状态，不会同步后续外部更新。狭窄空间下会自动翻转方位，实际显示位置可能不同于 placement。\n\n## 源码位置\n\n- 演示入口：`src/components/popover/PopoverDemo.tsx`\n- 相关实现：`src/components/popover`\n",
  "message": "# Message 全局提示\n\n通过 Provider 与 useMessage 展示成功、错误、警告、信息和加载消息。\n\n## 交互指南\n\n1. 依次点击不同类型按钮。\n2. 点击 Loading，观察约一秒后更新为成功提示。\n3. 对照 ConfigProvider 与 useMessage 阅读消息上下文和队列实现。\n\n## 在项目中运行\n\n点击本页的“运行演示”，或在独立窗口中体验示例。也可在 `src` 下的页面中直接挂载现有演示：\n\n```tsx\nimport Example from \"./components/message/MessageDemo\";\n\nexport default function ExamplePage() {\n  return <Example />;\n}\n```\n\n## API 与实现要点\n\n| 名称 | 类型或形式 | 说明 |\n| --- | --- | --- |\n| `ConfigProvider` | React component | 必须包裹使用 useMessage 的组件 |\n| `message.add` | function | 添加消息并返回 id |\n| `message.update` | function | 根据 id 更新已有消息 |\n| `content / type / position` | 消息配置 | 设置文字、类型与显示位置 |\n\n## 使用边界\n\n本项目自实现的 useMessage 与 antd.message 是两套不同接口；不要混用 Provider。演示的异步完成使用定时器模拟。\n\n## 源码位置\n\n- 演示入口：`src/components/message/MessageDemo.tsx`\n- 相关实现：`src/components/message`\n",
  "onBoarding": "# OnBoarding 漫游式引导\n\n通过选择器定位页面元素，结合遮罩和浮层展示分步操作引导。\n\n## 交互指南\n\n1. 进入演示后按引导逐步浏览目标按钮。\n2. 结束后点击重新演示再次运行。\n3. Link Button 可通过 ref.reStart() 重启。\n\n## 在项目中运行\n\n点击本页的“运行演示”，或在独立窗口中体验示例。也可在 `src` 下的页面中直接挂载现有演示：\n\n```tsx\nimport Example from \"./components/onBoarding/Demo\";\n\nexport default function ExamplePage() {\n  return <Example />;\n}\n```\n\n## API 与实现要点\n\n| 名称 | 类型或形式 | 说明 |\n| --- | --- | --- |\n| `steps` | array | 有序的步骤配置 |\n| `selector` | () => HTMLElement | null | 定位当前步骤的目标 |\n| `renderContent` | () => ReactNode | 渲染步骤说明 |\n| `placement` | string | 浮层方位 |\n| `ref.reStart` | () => void | 重新开始引导 |\n\n## 使用边界\n\nselector 必须在步骤显示时能找到目标。示例有外部图片，需要网络。遮罩覆盖页面属于此示例的预期效果。\n\n## 源码位置\n\n- 演示入口：`src/components/onBoarding/Demo.tsx`\n- 相关实现：`src/components/onBoarding`\n",
  "form": "# Form 表单组件\n\n通过 Context 收集字段值，使用 async-validator 校验表单。\n\n## 交互指南\n\n1. 清空用户名或密码后提交，查看必填错误。\n2. 输入超过 6 个字符的用户名，查看长度错误。\n3. 填写有效值提交，在开发者控制台观察 onFinish 输出。\n\n## 在项目中运行\n\n点击本页的“运行演示”，或在独立窗口中体验示例。也可在 `src` 下的页面中直接挂载现有演示：\n\n```tsx\nimport Example from \"./components/form/FormDemo\";\n\nexport default function ExamplePage() {\n  return <Example />;\n}\n```\n\n## API 与实现要点\n\n| 名称 | 类型或形式 | 说明 |\n| --- | --- | --- |\n| `initialValues` | object | 字段初始值 |\n| `onFinish` | function | 校验成功回调 |\n| `onFinishFailed` | function | 校验失败回调 |\n| `Form.Item.name / rules` | 字段配置 | 字段名与校验规则 |\n| `valuePropName` | string | Checkbox 使用 checked |\n\n## 使用边界\n\n演示没有真实登录请求，登录按钮仅触发表单校验。字段通过 name 注册，示例的输出位于控制台。\n\n## 源码位置\n\n- 演示入口：`src/components/form/FormDemo.tsx`\n- 相关实现：`src/components/form`\n",
  "upload": "# Upload 拖拽上传\n\n实现文件选择、拖拽上传、进度通知和上传结果回调。\n\n## 交互指南\n\n1. 先在项目根目录运行 npm run server，启动 3333 端口的上传服务。\n2. 点击上传区域选择图片，或将图片拖到区域内。\n3. 观察上传列表与控制台中的进度、成功或失败回调。\n\n## 在项目中运行\n\n点击本页的“运行演示”，或在独立窗口中体验示例。也可在 `src` 下的页面中直接挂载现有演示：\n\n```tsx\nimport Example from \"./components/upload/UploadDemo\";\n\nexport default function ExamplePage() {\n  return <Example />;\n}\n```\n\n## API 与实现要点\n\n| 名称 | 类型或形式 | 说明 |\n| --- | --- | --- |\n| `action` | string | 上传地址，本例 `http://localhost:3333/upload` |\n| `name` | string | 表单字段名，本例 file |\n| `drag` | boolean | 启用拖拽上传 |\n| `accept` | string | 本例 .png, .jpg, .jpeg |\n| `beforeUpload` | function | 返回 false 阻止上传 |\n| `onProgress / onSuccess / onError` | function | 进度与结果回调 |\n\n## 使用边界\n\nbeforeUpload 会拒绝名称含 1.image 的文件。accept 仅是客户端选择提示，服务端仍需校验文件。远程或 HTTPS 部署必须调整上传地址。\n\n## 源码位置\n\n- 演示入口：`src/components/upload/UploadDemo.tsx`\n- 相关实现：`src/components/upload`\n",
  "lazyload": "# Lazyload 懒加载\n\n通过 IntersectionObserver 在内容接近视口时渲染，配合占位骨架降低首屏开销。\n\n## 交互指南\n\n1. 在预览区域向下滚动到占位文字底部。\n2. 观察图片接近视口时替换骨架。\n3. 调整 offset 比较提前加载距离。\n\n## 在项目中运行\n\n点击本页的“运行演示”，或在独立窗口中体验示例。也可在 `src` 下的页面中直接挂载现有演示：\n\n```tsx\nimport Example from \"./components/lazyLoad/LazyloadDemo\";\n\nexport default function ExamplePage() {\n  return <Example />;\n}\n```\n\n## API 与实现要点\n\n| 名称 | 类型或形式 | 说明 |\n| --- | --- | --- |\n| `offset` | number / string | 观察区域 rootMargin，默认 0；本例 250 |\n| `placeholder` | ReactNode | 内容未可见时的占位 |\n| `width / height` | number / string | 占位尺寸 |\n| `onContentVisible` | () => void | 内容首次可见时回调 |\n\n## 使用边界\n\n示例图片来自外部站点，网络不可用时不会显示。首次相交后停止观察；离开视口不会卸载内容。\n\n## 源码位置\n\n- 演示入口：`src/components/lazyLoad/LazyloadDemo.tsx`\n- 相关实现：`src/components/lazyLoad`\n",
  "countDown": "# 倒计时\n\n将 useCountDown 的剩余时间展示为天、小时、分钟和秒。\n\n## 交互指南\n\n1. 进入演示查看距离下一年元旦的剩余时间。\n2. 等待一秒观察秒数变化。\n3. 需要不同截止时间时修改 targetDate。\n\n## 在项目中运行\n\n点击本页的“运行演示”，或在独立窗口中体验示例。也可在 `src` 下的页面中直接挂载现有演示：\n\n```tsx\nimport Example from \"./components/countDown/index\";\n\nexport default function ExamplePage() {\n  return <Example />;\n}\n```\n\n## API 与实现要点\n\n| 名称 | 类型或形式 | 说明 |\n| --- | --- | --- |\n| `targetDate` | string | 传给 useCountDown 的截止时间 |\n| `formattedRes` | object | 格式化剩余时间 |\n| `days / hours / minites / seconds` | number | 当前实现的字段名；分钟拼写为 minites |\n\n## 使用边界\n\n示例目标由浏览器当前年份计算，受本地时钟和时区影响。复用 Hook 时保持 minites 字段拼写与实现一致。\n\n## 源码位置\n\n- 演示入口：`src/components/countDown/index.tsx`\n- 相关实现：`src/components/countDown`\n",
  "slidInOverlay": "# SlideInOverlay 转场动画\n\n通过方向和显示状态控制覆盖层进入、离开动画。\n\n## 交互指南\n\n1. 点击 Bottom 从底部打开。\n2. 点击关闭观察离场回调提示。\n3. 点击 Right 比较从右侧进入效果。\n\n## 在项目中运行\n\n点击本页的“运行演示”，或在独立窗口中体验示例。也可在 `src` 下的页面中直接挂载现有演示：\n\n```tsx\nimport Example from \"./components/slideInOverlay/SlidInOverlayDemo\";\n\nexport default function ExamplePage() {\n  return <Example />;\n}\n```\n\n## API 与实现要点\n\n| 名称 | 类型或形式 | 说明 |\n| --- | --- | --- |\n| `isVisible` | boolean | 是否显示覆盖层 |\n| `from` | bottom / right | 进入方向 |\n| `duration` | number | 动画时长，本例 350 毫秒 |\n| `onEnter / onLeave` | function | 进入与离开回调 |\n\n## 使用边界\n\n使用父组件状态关闭覆盖层。演示通过消息展示生命周期回调，覆盖层可能超出预览区域。\n\n## 源码位置\n\n- 演示入口：`src/components/slideInOverlay/SlidInOverlayDemo.tsx`\n- 相关实现：`src/components/slideInOverlay`\n",
  "modal": "# Modal 模态框\n\n提供声明式挂载与静态方法两种打开模态框的方式。\n\n## 交互指南\n\n1. 点击 show model 打开挂载式弹窗。\n2. 输入内容，点击确定、取消或关闭。\n3. 点击静态方式调用，比较 Modal.show 与 Modal.hidden。\n\n## 在项目中运行\n\n点击本页的“运行演示”，或在独立窗口中体验示例。也可在 `src` 下的页面中直接挂载现有演示：\n\n```tsx\nimport Example from \"./components/modal/ModalDemo\";\n\nexport default function ExamplePage() {\n  return <Example />;\n}\n```\n\n## API 与实现要点\n\n| 名称 | 类型或形式 | 说明 |\n| --- | --- | --- |\n| `visible` | boolean | 声明式显示状态 |\n| `title / width` | 标题 / number | 弹窗标题与宽度 |\n| `onOk / onCancel / onClose` | function | 按钮与关闭回调 |\n| `Modal.show / Modal.hidden` | 静态方法 | 打开与关闭静态弹窗 |\n\n## 使用边界\n\n静态调用需在回调中主动调用 Modal.hidden。挂载式需要更新 visible。示例的确认操作只关闭弹窗并打印日志。\n\n## 源码位置\n\n- 演示入口：`src/components/modal/ModalDemo.tsx`\n- 相关实现：`src/components/modal`\n",
  "checkCard": "# CheckCard 多选卡片\n\n以卡片形式展示可选择项目，包含禁用、加载和分组选择。\n\n## 交互指南\n\n1. 点击基础卡片切换选中状态。\n2. 比较禁用、禁用选中和加载状态。\n3. 在 Group 中选择 A、B、C，查看多选结果。\n\n## 在项目中运行\n\n点击本页的“运行演示”，或在独立窗口中体验示例。也可在 `src` 下的页面中直接挂载现有演示：\n\n```tsx\nimport Example from \"./components/checkCard/CheckCardDemo\";\n\nexport default function ExamplePage() {\n  return <Example />;\n}\n```\n\n## API 与实现要点\n\n| 名称 | 类型或形式 | 说明 |\n| --- | --- | --- |\n| `title / description / avatar` | 内容配置 | 卡片文字与头像 |\n| `defaultChecked / disabled / loading` | boolean | 初始选中、禁用和加载 |\n| `onChange` | function | 选中变化通知 |\n| `CheckCard.Group.multiple` | boolean | 开启分组多选 |\n| `value / initValue` | 选项值 / 初始值 | 卡片标识与组初始选择 |\n\n## 使用边界\n\nextra 内的按钮需要 stopPropagation，避免点击操作时切换卡片选中。示例头像来自外部 CDN。\n\n## 源码位置\n\n- 演示入口：`src/components/checkCard/CheckCardDemo.tsx`\n- 相关实现：`src/components/checkCard`\n",
  "tab": "# Tab 标签页\n\n将内容按标签切换，提供线条、卡片和不同尺寸样式。\n\n## 交互指南\n\n1. 切换 React、Vue、Angular 标签。\n2. 点击禁用项，确认内容不会切换。\n3. 查看小尺寸与卡片样式示例。\n\n## 在项目中运行\n\n点击本页的“运行演示”，或在独立窗口中体验示例。也可在 `src` 下的页面中直接挂载现有演示：\n\n```tsx\nimport Example from \"./components/Tab/index\";\n\nexport default function ExamplePage() {\n  return <Example />;\n}\n```\n\n## API 与实现要点\n\n| 名称 | 类型或形式 | 说明 |\n| --- | --- | --- |\n| `defaultActive` | string | 初始选中项 name |\n| `onChange` | (name: string) => void | 切换通知 |\n| `size` | small / default / large | 标签尺寸 |\n| `type` | line / card | 视觉样式 |\n| `TabItem.name / label / disabled` | 子项配置 | 名称、标签与禁用状态 |\n\n## 使用边界\n\n可复用的 Tab 和 TabItem 从 Tab.tsx 命名导出，目录 index.tsx 默认导出的是演示页。defaultActive 仅设置初始选择。\n\n## 源码位置\n\n- 演示入口：`src/components/Tab/index.tsx`\n- 相关实现：`src/components/Tab`\n",
  "reactSpring1": "# react-spring 单元素动画\n\n比较 useSpringValue、useSpring 与命令式 api.start 三种动画写法。\n\n## 交互指南\n\n1. 观察前两项自动增长。\n2. 点击 Demo3 启动宽度变化。\n3. 点击工作台的重置演示，重新播放。\n\n## 在项目中运行\n\n点击本页的“运行演示”，或在独立窗口中体验示例。也可在 `src` 下的页面中直接挂载现有演示：\n\n```tsx\nimport Example from \"./third-party-lib/react-spring/spring-1/SpringBox1\";\n\nexport default function ExamplePage() {\n  return <Example />;\n}\n```\n\n## API 与实现要点\n\n| 名称 | 类型或形式 | 说明 |\n| --- | --- | --- |\n| `useSpringValue` | Hook | 驱动单个数值 |\n| `useSpring` | Hook | 驱动样式对象 |\n| `api.start` | function | 命令式启动动画 |\n| `config` | object | 配置 mass、friction、tension 或 duration |\n\n## 使用边界\n\n此页是无 props 的教学演示。动画目标宽度为 400；实际应用中应按容器尺寸计算。\n\n## 源码位置\n\n- 演示入口：`src/third-party-lib/react-spring/spring-1/SpringBox1.tsx`\n- 相关实现：`src/third-party-lib/react-spring/spring-1`\n",
  "reactSpring2": "# react-spring 多元素动画\n\n对比多组弹簧与跟随式动画，理解多个元素的运动关系。\n\n## 交互指南\n\n1. 观察同时执行与依次执行两列。\n2. 重置演示重新比较启动过程。\n3. 在源文件中调整 duration 或目标宽度。\n\n## 在项目中运行\n\n点击本页的“运行演示”，或在独立窗口中体验示例。也可在 `src` 下的页面中直接挂载现有演示：\n\n```tsx\nimport Example from \"./third-party-lib/react-spring/spring-2/SpringBox2\";\n\nexport default function ExamplePage() {\n  return <Example />;\n}\n```\n\n## API 与实现要点\n\n| 名称 | 类型或形式 | 说明 |\n| --- | --- | --- |\n| `useSprings` | Hook | 创建多个可单独控制的动画 |\n| `useTrail` | Hook | 创建相互跟随的动画序列 |\n| `api.start` | function | 挂载时把宽度动画到容器可用列宽，不超过 400 |\n\n## 使用边界\n\n示例内部创建三项动画，不对外提供 props。useTrail 的效果由弹簧跟随产生，不是业务任务队列。\n\n## 源码位置\n\n- 演示入口：`src/third-party-lib/react-spring/spring-2/SpringBox2.tsx`\n- 相关实现：`src/third-party-lib/react-spring/spring-2`\n",
  "reactSpring3": "# react-spring 复杂动画\n\n使用 useSpringRef 和 useChain 编排多组样式动画。\n\n## 交互指南\n\n1. 进入演示观察宽度和高度变化。\n2. 重置演示重复播放。\n3. 修改 useChain 的时间参数比较动画重叠关系。\n\n## 在项目中运行\n\n点击本页的“运行演示”，或在独立窗口中体验示例。也可在 `src` 下的页面中直接挂载现有演示：\n\n```tsx\nimport Example from \"./third-party-lib/react-spring/spring-3/SpringBox3\";\n\nexport default function ExamplePage() {\n  return <Example />;\n}\n```\n\n## API 与实现要点\n\n| 名称 | 类型或形式 | 说明 |\n| --- | --- | --- |\n| `useSpringRef` | Hook | 创建动画组引用 |\n| `useSprings` | Hook | 本例分别驱动 width 与 height |\n| `useChain` | Hook | 组合引用与相对时间偏移 |\n\n## 使用边界\n\n源码使用 useChain([api1, api2], [0, 1], 500)，第二组按时间偏移启动，不保证等待第一组完成。\n\n## 源码位置\n\n- 演示入口：`src/third-party-lib/react-spring/spring-3/SpringBox3.tsx`\n- 相关实现：`src/third-party-lib/react-spring/spring-3`\n",
  "reactSprings": "# react-spring 综合应用\n\n在 SVG 网格中组合线条绘制和方块缩放动画。\n\n## 交互指南\n\n1. 观察网格线条逐步展开。\n2. 继续观察方块按延迟出现。\n3. 点击重置演示重新播放整个序列。\n\n## 在项目中运行\n\n点击本页的“运行演示”，或在独立窗口中体验示例。也可在 `src` 下的页面中直接挂载现有演示：\n\n```tsx\nimport Example from \"./third-party-lib/react-spring/springs/Springs\";\n\nexport default function ExamplePage() {\n  return <Example />;\n}\n```\n\n## API 与实现要点\n\n| 名称 | 类型或形式 | 说明 |\n| --- | --- | --- |\n| `useTrail` | Hook | 生成网格线动画 |\n| `useSprings` | Hook | 驱动七个方块 scale |\n| `useChain` | Hook | 编排网格和方块 |\n| `COORDS` | 坐标数组 | 指定方块在 SVG 中的位置 |\n\n## 使用边界\n\n尺寸与坐标是 SVG viewBox 内的单位。animated.line 和 animated.rect 接收弹簧值，不需要每一帧手动 setState。\n\n## 源码位置\n\n- 演示入口：`src/third-party-lib/react-spring/springs/Springs.tsx`\n- 相关实现：`src/third-party-lib/react-spring/springs`\n",
  "ReactDnd1": "# react-dnd 普通拖拽\n\n展示拖拽源、放置目标、自定义拖拽预览和目标状态反馈。\n\n## 交互指南\n\n1. 按住源区域中的色块并拖动。\n2. 移入目标区域观察高亮。\n3. 松开后观察目标区域的数据变化。\n\n## 在项目中运行\n\n点击本页的“运行演示”，或在独立窗口中体验示例。也可在 `src` 下的页面中直接挂载现有演示：\n\n```tsx\nimport Example from \"./third-party-lib/react-dnd/react-dnd-1/Page\";\n\nexport default function ExamplePage() {\n  return <Example />;\n}\n```\n\n## API 与实现要点\n\n| 名称 | 类型或形式 | 说明 |\n| --- | --- | --- |\n| `DndProvider` | React component | 本例使用 HTML5Backend |\n| `useDrag` | Hook | 声明 box 拖拽类型与载荷 |\n| `useDrop` | Hook | 接收 box 并通过 drop 更新数据 |\n| `isOver / canDrop` | monitor 状态 | 控制目标反馈 |\n\n## 使用边界\n\nHTML5Backend 主要面向桌面拖拽；触摸支持需另行配置后端。拖拽类型必须与目标 accept 匹配。\n\n## 源码位置\n\n- 演示入口：`src/third-party-lib/react-dnd/react-dnd-1/Page.tsx`\n- 相关实现：`src/third-party-lib/react-dnd/react-dnd-1`\n",
  "ReactDnd2": "# react-dnd 拖拽排序\n\n卡片同时作为拖拽源和目标，在悬停时交换列表位置。\n\n## 交互指南\n\n1. 按住一张卡片。\n2. 拖过其他卡片观察顺序变化。\n3. 松开结束拖拽，重置演示恢复初始列表。\n\n## 在项目中运行\n\n点击本页的“运行演示”，或在独立窗口中体验示例。也可在 `src` 下的页面中直接挂载现有演示：\n\n```tsx\nimport Example from \"./third-party-lib/react-dnd/react-dnd-2/DndPage2\";\n\nexport default function ExamplePage() {\n  return <Example />;\n}\n```\n\n## API 与实现要点\n\n| 名称 | 类型或形式 | 说明 |\n| --- | --- | --- |\n| `Card.data` | CardItem | id 与 content |\n| `Card.index` | number | 当前列表位置 |\n| `Card.swap` | function | 交换来源与目标位置 |\n| `DragData` | object | 拖拽载荷包含 id 与 index |\n\n## 使用边界\n\n此例在 hover 中交换位置，并更新拖拽项 index。排序只保存在当前组件状态，不会写入服务器。\n\n## 源码位置\n\n- 演示入口：`src/third-party-lib/react-dnd/react-dnd-2/DndPage2.tsx`\n- 相关实现：`src/third-party-lib/react-dnd/react-dnd-2`\n",
  "UseGesture": "# use-gesture 图片轮播\n\n将拖拽手势与弹簧动画组合成可自动播放的图片轮播。\n\n## 交互指南\n\n1. 左右拖动图片体验翻页。\n2. 点击底部圆点跳转到指定图片。\n3. 等待约三秒观察自动轮播，点击顶部彩色区域查看示例源码。\n\n## 在项目中运行\n\n点击本页的“运行演示”，或在独立窗口中体验示例。也可在 `src` 下的页面中直接挂载现有演示：\n\n```tsx\nimport Example from \"./third-party-lib/use-gestrue/GestureDemo\";\n\nexport default function ExamplePage() {\n  return <Example />;\n}\n```\n\n## API 与实现要点\n\n| 名称 | 类型或形式 | 说明 |\n| --- | --- | --- |\n| `useDrag` | Hook | 读取 movement、direction 和 active |\n| `useSprings` | Hook | 驱动每页位移与缩放 |\n| `activeIndex` | number | 当前页索引 |\n| `pages` | string[] | 示例图片 URL 列表 |\n\n## 使用边界\n\n图片依赖外部网络。组件目前没有对外配置接口，自动轮播间隔在源文件中固定为 3000 毫秒。\n\n## 源码位置\n\n- 演示入口：`src/third-party-lib/use-gestrue/GestureDemo.tsx`\n- 相关实现：`src/third-party-lib/use-gestrue`\n",
  "zustand": "# my-zustand 状态管理\n\n实现简化版外部状态容器，并通过 useSyncExternalStore 让嵌套组件订阅共享状态。\n\n## 交互指南\n\n1. 在第一个输入框输入文本。\n2. 观察下方 aaa 同步变化。\n3. 修改第二个输入框，观察 bbb；切换演示不会自动清除模块级 store。\n\n## 在项目中运行\n\n点击本页的“运行演示”，或在独立窗口中体验示例。也可在 `src` 下的页面中直接挂载现有演示：\n\n```tsx\nimport Example from \"./zustand/TestZustand\";\n\nexport default function ExamplePage() {\n  return <Example />;\n}\n```\n\n## API 与实现要点\n\n| 名称 | 类型或形式 | 说明 |\n| --- | --- | --- |\n| `create` | function | 通过 set、get 和 api 创建 store |\n| `selector` | function | 从 store 选择所需字段 |\n| `setState` | function | 更新并通知订阅者 |\n| `subscribe` | function | 注册监听并返回取消订阅函数 |\n\n## 使用边界\n\n这是教学实现，不等同于官方 Zustand 的完整功能。此例状态存在内存中，刷新页面后重置。\n\n## 源码位置\n\n- 演示入口：`src/zustand/TestZustand.jsx`\n- 相关实现：`src/zustand`\n",
  "toComponent": "# click-to-component 开发定位\n\n展示通过页面元素定位 React 组件源码的开发辅助工具。\n\n## 交互指南\n\n1. 在本地开发模式打开示例。\n2. 按住 Option（macOS）或 Alt，在目标元素上点击。\n3. 根据工具提示选择组件，并尝试在本地编辑器中打开源文件。\n\n## 在项目中运行\n\n点击本页的“运行演示”，或在独立窗口中体验示例。也可在 `src` 下的页面中直接挂载现有演示：\n\n```tsx\nimport Example from \"./third-party-lib/click-to-component/index\";\n\nexport default function ExamplePage() {\n  return <Example />;\n}\n```\n\n## API 与实现要点\n\n| 名称 | 类型或形式 | 说明 |\n| --- | --- | --- |\n| `ClickToComponent` | React component | 项目入口已挂载的开发辅助组件 |\n| `Aaa / Bbb` | 示例组件 | 提供嵌套元素用于定位 |\n\n## 使用边界\n\n定位与打开编辑器依赖本地开发环境和编辑器协议配置。生产构建不能作为完整源码浏览服务。\n\n## 源码位置\n\n- 演示入口：`src/third-party-lib/click-to-component/index.tsx`\n- 相关实现：`src/third-party-lib/click-to-component`\n",
  "reactFlowBase": "# React Flow 基础使用\n\n演示自定义节点、连线、连线删除、缩放控件和小地图。\n\n## 交互指南\n\n1. 拖动节点改变位置。\n2. 从节点连接点拖出新连线。\n3. 点击连线上的 × 删除；点击添加节点创建新节点。\n\n## 在项目中运行\n\n点击本页的“运行演示”，或在独立窗口中体验示例。也可在 `src` 下的页面中直接挂载现有演示：\n\n```tsx\nimport Example from \"./third-party-lib/react-flow/base-use/FlowBase\";\n\nexport default function ExamplePage() {\n  return <Example />;\n}\n```\n\n## API 与实现要点\n\n| 名称 | 类型或形式 | 说明 |\n| --- | --- | --- |\n| `nodes / edges` | 数组 | 图的受控节点和连线数据 |\n| `onNodesChange / onEdgesChange` | function | 处理图编辑 |\n| `onConnect` | function | 连接两个端点 |\n| `nodeTypes / edgeTypes` | 映射 | 注册自定义节点和连线 |\n\n## 使用边界\n\n图数据仅存在页面状态中。React Flow 父容器必须有明确宽高。业务使用时应把类型映射放在组件外以保持引用稳定。\n\n## 源码位置\n\n- 演示入口：`src/third-party-lib/react-flow/base-use/FlowBase.tsx`\n- 相关实现：`src/third-party-lib/react-flow/base-use`\n",
  "reactFlowAudioPlay": "# React Flow 音频播放\n\n把 Web Audio 振荡器、音量和输出节点映射为可编辑的音频连接图。\n\n## 交互指南\n\n1. 查看初始振荡器 → 音量 → 输出链路。\n2. 调整节点内的频率、波形和音量控件。\n3. 添加节点并拖动连接点；删除连线观察音频图同步断开。\n\n## 在项目中运行\n\n点击本页的“运行演示”，或在独立窗口中体验示例。也可在 `src` 下的页面中直接挂载现有演示：\n\n```tsx\nimport Example from \"./third-party-lib/react-flow/audio-player/AudioPlayer\";\n\nexport default function ExamplePage() {\n  return <Example />;\n}\n```\n\n## API 与实现要点\n\n| 名称 | 类型或形式 | 说明 |\n| --- | --- | --- |\n| `osc` | 节点类型 | 振荡器，包含 frequency 与 type |\n| `volume` | 节点类型 | 增益节点，包含 gain |\n| `out` | 节点类型 | 音频输出 |\n| `connect / disconnect` | function | 同步画布连接与音频连接 |\n\n## 使用边界\n\n需要浏览器支持 Web Audio；播放可能需要先进行用户交互。节点与连接状态是演示数据，尚未提供导出和保存功能。\n\n## 源码位置\n\n- 演示入口：`src/third-party-lib/react-flow/audio-player/AudioPlayer.tsx`\n- 相关实现：`src/third-party-lib/react-flow/audio-player`\n",
  "audioContext": "# Web Audio 在线钢琴\n\n通过振荡器和增益包络合成简单琴音，无需音频文件。\n\n## 交互指南\n\n1. 点击琴键播放对应音符。\n2. 使用键盘 A、S、D、F、G、H、J、K 演奏。\n3. 观察琴键按下反馈和约一秒的声音衰减。\n\n## 在项目中运行\n\n点击本页的“运行演示”，或在独立窗口中体验示例。也可在 `src` 下的页面中直接挂载现有演示：\n\n```tsx\nimport Example from \"./third-party-lib/react-flow/online-piano/index\";\n\nexport default function ExamplePage() {\n  return <Example />;\n}\n```\n\n## API 与实现要点\n\n| 名称 | 类型或形式 | 说明 |\n| --- | --- | --- |\n| `keys` | Record | 键名到频率的映射 |\n| `OscillatorNode` | Web Audio | 生成 sine 波形 |\n| `GainNode` | Web Audio | 控制音量包络 |\n\n## 使用边界\n\n需要浏览器支持 AudioContext，并可能要求先点击页面以允许声音。黑键是装饰元素，当前只实现八个白键音符。\n\n## 源码位置\n\n- 演示入口：`src/third-party-lib/react-flow/online-piano/index.tsx`\n- 相关实现：`src/third-party-lib/react-flow/online-piano`\n",
  "todolist": "# TodoList 拖拽待办\n\n组合拖拽交互、待办状态和 Zustand 持久化，完成一个小型任务列表。\n\n## 交互指南\n\n1. 通过新增区域创建任务。\n2. 拖动任务到列表间隙调整位置。\n3. 切换任务状态，或拖到垃圾桶删除。\n\n## 在项目中运行\n\n点击本页的“运行演示”，或在独立窗口中体验示例。也可在 `src` 下的页面中直接挂载现有演示：\n\n```tsx\nimport Example from \"./ts-projects/dnd-todo-list/TodoListDemo\";\n\nexport default function ExamplePage() {\n  return <Example />;\n}\n```\n\n## API 与实现要点\n\n| 名称 | 类型或形式 | 说明 |\n| --- | --- | --- |\n| `ListItem` | object | id、content 与 todo/done 状态 |\n| `addItem(item, id?)` | function | 追加或插入到指定任务前 |\n| `updateItem(item)` | function | 按 id 更新任务 |\n| `deleteItem(id)` | function | 移除任务 |\n\n## 使用边界\n\n任务存储在当前浏览器 localStorage 的 todoList 中。工作台重置演示只重新挂载组件，不会清除持久化任务。没有服务端同步，删除操作未提供撤销。\n\n## 源码位置\n\n- 演示入口：`src/ts-projects/dnd-todo-list/TodoListDemo.tsx`\n- 相关实现：`src/ts-projects/dnd-todo-list`\n"
};
